import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"二分图匹配","description":"","frontmatter":{"title":"二分图匹配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bipartite-match.md","filePath":"cs/bipartite-match.md","lastUpdated":1789023840000}'),h={name:"cs/bipartite-match.md"};function E(m,a,_,f,u,B){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="二分图匹配" tabindex="-1">二分图匹配 <a class="header-anchor" href="#二分图匹配" aria-label="Permalink to &quot;二分图匹配&quot;">​</a></h1><div class="epigraph"><p>最大匹配等于最小点覆盖；单位容量网络上最大流给出最大匹配。</p><footer>—— 据 König, 1931；Hopcroft and Karp, An $n^{5/2}$ Algorithm for Maximum Matchings in Bipartite Graphs, 1973；CLRS 第 26.3 节整理</footer></div><p>上一课<a href="/cs/dinic">Edmonds–Karp 与 Dinic</a>把最大流变成多项式增广。本课不重写分层。缺口是组合对象<strong>匹配</strong>：边子集、任意点至多关联一条。二分图 \\(G=(L\\cup R,E)\\) 上，最大基数匹配等于以 \\(s\\to L\\to R\\to t\\)、边容量 \\(1\\) 的最大流。König：最大匹配 = 最小点覆盖。后课离开图，进入串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贪心随便取边得不到最大。交错路：从自由点出发，非匹配/匹配交替，增广路定理（Berge）说匹配最大当且仅当无增广路——与残量 \\(s\\)–\\(t\\) 路同一图像。构造网络：超源连 \\(L\\) 容量 \\(1\\)，\\(R\\) 连超汇容量 \\(1\\)，原边 \\(L\\to R\\) 容量 \\(1\\)。整流对应匹配。缺口是这层翻译，不是再证最大流最小割。</p><p>Hall 条件：对任意 \\(S\\subseteq L\\)，\\(|N(S)|\\ge|S|\\) 当且仅当存在饱和 \\(L\\) 的匹配。本课点名，不把婚配定理证完。</p><h3 id="一般图不是本课" tabindex="-1">一般图不是本课 <a class="header-anchor" href="#一般图不是本课" aria-label="Permalink to &quot;一般图不是本课&quot;">​</a></h3><p>带花的 Edmonds 算法处理非二分；本课只二分。不要把「每次找一条交错路」在奇环上当多项式显然。</p><p><span class="marginnote">König 定理是二分图上最大匹配/最小覆盖的对偶。Hopcroft–Karp 1973 一次找一组最短增广，时间 \\(O(E\\sqrt V)\\)，与单位容量 Dinic 同类。CLRS 26.3 用流做匹配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建单位网络，跑上一课的最大流。匹配边即 \\(L\\to R\\) 上流量为 \\(1\\) 的边。最小点覆盖：最大流后残量里 \\(s\\) 可达的 \\(L\\) 与不可达的 \\(R\\) 等标准构造，本课认「覆盖数等于匹配数」，不手画全部情形。</p>',11)),(e(),l(c,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BG%5B%22%E4%BA%8C%E5%88%86%E5%9B%BE%22%5D%20--%3E%20NET%5B%22s-L-R-t%20%E5%8D%95%E4%BD%8D%E5%AE%B9%E9%87%8F%22%5D%0A%20%20NET%20--%3E%20FLOW%5B%22%E6%9C%80%E5%A4%A7%E6%B5%81%22%5D%0A%20%20FLOW%20--%3E%20M%5B%22%E6%9C%80%E5%A4%A7%E5%8C%B9%E9%85%8D%22%5D%0A%20%20M%20--%3E%20K%5B%22%E6%9C%80%E5%B0%8F%E7%82%B9%E8%A6%86%E7%9B%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>匈牙利算法是交错路的直接实现，与单位流增广等价。本课以流为接口，避免两套术语。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>整数容量保证整流。多源任务分配：左边人、右边岗位，即本课。权匹配（KM / 费用流）不在本课。也不要把 MST 的边集当匹配：度数可以大于 \\(1\\)。</p><p><a href="/cs/dfs-edge-types">DFS 边分类</a>的交错路是这条图上的路径，不是 DFS 森林的四类边。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做一般图匹配、不做稳定婚配的 Gale–Shapley。后课默认：二分最大匹配 = 单位最大流，基数多项式可算。串匹配是另一类对象：文本与模式，不是点对边。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二分最大匹配 ↔ 单位容量最大流。</li><li>最大匹配 = 最小点覆盖（König）。</li><li>一般图带花，不在本课。</li><li>出处：König；Hopcroft and Karp, 1973；CLRS 第 26.3 节。</li></ul>',8))])}const S=o(h,[["render",E]]);export{A as __pageData,S as default};
